/**
 * withAndroidR8 -- enable R8 minification (obfuscation) + resource shrinking in release builds.
 * Google Play flags "DEX code optimization is below our threshold" (obfuscation) otherwise.
 *
 * Applied to the generated android/gradle.properties (gitignored, regenerated by `expo prebuild`).
 * Keep rules live in android/app/proguard-rules.pro; see README "Release builds: R8 obfuscation".
 */
const { withGradleProperties } = require('@expo/config-plugins')

const PROPS = {
  'android.enableMinifyInReleaseBuilds': 'true',
  'android.enableShrinkResourcesInReleaseBuilds': 'true',
}

module.exports = function withAndroidR8(config) {
  return withGradleProperties(config, (config) => {
    for (const [key, value] of Object.entries(PROPS)) {
      const existing = config.modResults.find((p) => p.type === 'property' && p.key === key)
      if (existing) existing.value = value
      else config.modResults.push({ type: 'property', key, value })
    }
    return config
  })
}
